<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{selected?selected.payload.name:rule?'佣金规则详情':'合作协议详情'}}</h2><p v-if="selected">{{storeName}} <StatusTag :value="selected.status"/></p><p v-if="selected" class="ui-meta">{{rule?selected.ruleKey:selected.number}} · 提交 v{{selected.revision}} · 数据 v{{selected.version}} · 编号 {{selected.id}}</p></div><div class="ui-actions"><Button @click="back">返回列表</Button><Button @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div v-if="selected"><Alert v-if="selected.status!=='DRAFT'" show-icon>此版本正文只读。实质变更需创建新版本，不能原地覆盖。</Alert><Tabs v-model="tab" :animated="false"><TabPane :label="rule?'规则条款':'协议正文'" name="overview"><DetailSection title="关联对象与有效窗口"><FieldRow label="商户" :value="storeName"/><FieldRow label="适用业务" value="P0商城"/><FieldRow v-if="rule" label="关联协议" :value="agreementName"/><FieldRow v-if="rule" label="引用协议版本" :value="selected.agreementRevision"/><FieldRow label="开始日期" :value="selected.payload.startDate"/><FieldRow label="截止日期（含当日）" :value="selected.payload.endDate"/><FieldRow label="实际生效开始" :value="date(selected.actualFrom)"/><FieldRow label="实际生效截止（不含）" :value="date(selected.actualTo)"/></DetailSection><DetailSection v-if="!rule" title="协议主体与确认"><FieldRow label="平台主体" :value="selected.payload.platformLegalName"/><FieldRow label="商户主体" :value="selected.payload.merchantLegalName"/><FieldRow label="统一社会信用代码" :value="selected.payload.merchantLegalCode"/><FieldRow label="双方确认凭据" :value="selected.payload.confirmationReference" wide/><FieldRow label="确认时间" :value="date(selected.confirmedAt)"/><FieldRow label="合作类目" wide><CategoryNames :ids="selected.payload.categoryIds||[]" purpose="cooperation"/></FieldRow></DetailSection><DetailSection title="商务口径"><FieldRow label="佣金比例" :value="percent(selected.payload.rateBps)"/><FieldRow label="计费基数" value="商品实付，不含运费"/><FieldRow label="取整方式" value="向下取整到分"/><FieldRow label="佣金条款" :value="selected.payload.commissionClause" wide/><FieldRow v-if="!rule" label="退款摘要" :value="selected.payload.refundSummary" wide/><template v-if="rule"><FieldRow label="未来执行依据" value="订单完成且无阻断性售后／退款" wide/><FieldRow label="自动执行商业意向" :value="selected.payload.executionIntent"/><FieldRow label="当前资金执行" value="关闭"/><FieldRow label="版本备注" :value="selected.payload.note" wide/></template></DetailSection><RulePreview v-if="rule" :key="selected.id" :rule="selected"/></TabPane><TabPane v-if="!rule" label="附件与确认材料" name="files"><AttachmentList :key="selected.id" :value="selected.payload.fileIds||[]" purpose="AGREEMENT"/><p class="ui-note">商户端只读查看不构成电子签署。</p></TabPane><TabPane label="版本历史" name="history"><HistoryTable :records="versions.map(r=>({...r,name:r.payload.name,start:r.payload.startDate,end:r.payload.endDate,at:r.publishedAt||r.confirmedAt}))" :columns="historyColumns"><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">查看此版本</Button></template></HistoryTable></TabPane><TabPane label="生效与操作记录" name="actions"><DetailSection title="版本事件"><FieldRow label="确认／发布时间" :value="date(rule?selected.publishedAt:selected.confirmedAt)"/><FieldRow label="停用／终止时间" :value="date(rule?selected.disabledAt:selected.terminatedAt)"/><FieldRow label="续约截断时间" :value="date(selected.replacedAt)"/><FieldRow label="前序版本编号" :value="selected.predecessorId"/><FieldRow label="终止原因" v-if="!rule" :value="selected.reason" wide/><FieldRow v-if="rule" label="真实渠道判定" :value="status(selected.realChannelValidation)"/></DetailSection><HistoryTable :records="auditRows" :columns="auditColumns"/><Page class="ui-pagination" :total="auditTotal" :current="auditPage" :page-size="20" show-total @on-change="auditPage=$event;loadAudit()"/></TabPane></Tabs><footer class="ui-footer-actions"><Button @click="back">返回列表</Button><template v-if="writable"><Button v-if="selected.status==='DRAFT'" :disabled="blocked" @click="edit(false)">编辑草稿</Button><Button v-else :disabled="blocked" @click="edit(true)">创建续约版本</Button><Button v-if="selected.status==='DRAFT'" type="primary" :disabled="blocked" @click="execute(rule?'publish':'confirm')">{{rule?'发布当前规则':'确认当前协议'}}</Button><Button v-if="!rule&&selected.status==='CONFIRMED'" :disabled="blocked" @click="execute('cancel')">取消待生效协议</Button><Button v-if="!rule&&selected.status==='EFFECTIVE'" type="error" :disabled="blocked" @click="execute('terminate')">终止协议</Button><Button v-if="rule&&['EFFECTIVE','CONFIRMED'].includes(selected.status)" type="warning" :disabled="blocked" @click="execute('disable')">停用规则</Button></template></footer></div><CooperationForm :visible="show" :rule="rule" :record="editing" :previous="previous" :busy="busy" :disabled="blocked" :error="error" @dirty="dirty=true" @save="save" @cancel="cancel"/></Card></template>
<script>import page from '../page';import PageStatus from './PageStatus';import StatusTag from './StatusTag';import DetailSection from './DetailSection';import FieldRow from './FieldRow';import CategoryNames from './CategoryNames';import AttachmentList from './AttachmentList';import HistoryTable from './HistoryTable';import CooperationForm from './CooperationForm';import RulePreview from './RulePreview';import {stage1Confirm} from '../../confirm';export default {mixins:[page],components:{PageStatus,StatusTag,DetailSection,FieldRow,CategoryNames,AttachmentList,HistoryTable,CooperationForm,RulePreview},props:{rule:Boolean},data:()=>({auditRows:[],auditTotal:0,auditPage:1,auditTicket:0,auditColumns:[{title:'时间（上海）',slot:'time',minWidth:180},{title:'操作',slot:'action',minWidth:150},{title:'人员',key:'operatorName',minWidth:140},{title:'原版本',key:'beforeVersion',width:90},{title:'新版本',key:'afterVersion',width:90},{title:'操作原因',key:'reason',minWidth:240}],show:false,editing:null,previous:null,versions:[],storeName:'未提供',agreementName:'未提供',historyColumns:[{title:'版本',key:'revision',width:80},{title:'名称',key:'name',minWidth:160},{title:'状态',slot:'state',width:115},{title:'起期',key:'start',minWidth:130},{title:'止期（含当日）',key:'end',minWidth:150},{title:'操作',slot:'operations',width:130}]}),computed:{path(){return this.rule?'/commission-rules':'/agreements';},writable(){return this.can(this.rule?'rule.write':'agreement.write');}},watch:{'$route.params.id'(){this.auditTicket++;this.auditPage=1;this.auditRows=[];this.show=false;this.tab='overview';this.reload();}},mounted(){this.reload();},beforeDestroy(){this.auditTicket++;},methods:{async loadAudit(){if(!this.selected)return;const row=this.selected,ticket=++this.auditTicket,type=this.rule?'RULE':'AGREEMENT';this.auditRows=[];this.auditTotal=0;try{const v=await this.ui('/stores/'+row.storeId+'/history',{objectType:type,objectId:row.id,pageNumber:this.auditPage,pageSize:20});if(ticket!==this.auditTicket||!this.selected||this.selected.id!==row.id)return;if(v.objectType!==type||v.objectId!==row.id)throw Error('当前API未提供该对象的授权操作历史。');this.auditRows=v.records;this.auditTotal=v.total;}catch(e){if(ticket===this.auditTicket)this.error=e.message;}},reload(){return this.latest(async()=>{const id=this.$route.params.id;const [row,versions]=await Promise.all([this.read(this.path+'/'+id),this.read(this.path+'/'+id+'/versions')]);const lookup=await this.ui('/lookups/stores',{selected:row.storeId,pageSize:1});let agreementName='未提供';if(this.rule&&this.can('agreement.read')){const a=await this.read('/agreements/'+row.agreementId);agreementName=(a.payload.name||a.number)+' · v'+a.revision;}return {row,versions,storeName:lookup.records[0]&&lookup.records[0].name||'名称未提供',agreementName};},v=>{this.selected=v.row;this.loadAudit();this.versions=v.versions;this.storeName=v.storeName;this.agreementName=v.agreementName;},()=>{this.selected=null;this.versions=[];});},edit(renew){this.editing=renew?null:this.selected;this.previous=renew?this.selected:null;this.show=true;},async save({record,previous,header,payload}){try{const body=record?{expectedVersion:record.version,payload}:{...header,businessType:'MALL',...(previous?{predecessorId:previous.id}:{}),payload};if(!this.rule)delete body.agreementId;const result=await this.run(this.path+(record?'/'+record.id+'/draft':''),body,record?'PUT':'POST');if(result){this.show=false;this.dirty=false;if(result.id!==this.selected.id)this.detail(result.id);else await this.reload();}}catch(_){}},cancel(){if(this.uploading)return;const close=()=>{this.show=false;this.dirty=false;};if(this.dirty)stage1Confirm({title:'放弃未保存输入？',content:'关闭不会保存当前草稿。',onOk:close});else close();},async execute(action){const row=this.selected;const titles={confirm:'确认协议后正文不可覆盖',publish:'发布当前规则版本',cancel:'取消待生效协议',terminate:'终止当前协议',disable:'停用当前规则'};const result=await this.command(this.path+'/'+row.id+'/'+action,titles[action],{expectedVersion:row.version},this.storeName+' · '+row.payload.name+' · v'+row.revision+'。校验时间窗口和当前事实，不产生资金执行。');if(result)await this.reload();}}};</script>
